      solutionSteps: [{ op: 'removeTop', a: { n: '1' } }, { op: 'promote', a: {} }, { op: 'fillDown', a: { col: 'Almacén' } }, { op: 'type', a: { col: 'Existencia', to: 'Número entero' } }, { op: 'type', a: { col: 'Costo', to: 'Número decimal' } }],
