        solutionSteps: [{ op: 'split', a: { col: 'Empleado', delim: ',' } }, { op: 'rename', a: { col: 'Empleado.1', name: 'Apellido' } }, { op: 'rename', a: { col: 'Empleado.2', name: 'Nombre' } }, { op: 'trim', a: { col: 'Área' } }, { op: 'proper', a: { col: 'Área' } }],
