  D('py-1', 'Este código falla con un TypeError. Corrígelo para que imprima "Total: 750".', 'precio = 250\ncantidad = 3\nprint("Total: " + precio * cantidad)', 'precio = 250\ncantidad = 3\nprint(f"Total: {precio * cantidad}")', ['No se puede sumar texto con un número.', 'Usa una f-string: f"Total: {precio * cantidad}".']);
