  P('py-4', 'total = 0\nfor i in range(1, 4):\n    total += i * 10\nprint(total)\nprint([1, 2, 3][-1] + len([4, 5]))', 'range(1, 4) es 1, 2, 3: 10 + 20 + 30 = 60. El último de la lista es 3 y la otra lista tiene 2 elementos.');
  D('py-4', 'Debería imprimir 600 pero no corre. Corrígelo.', 'ventas = [100, 200, 300]\ntotal = 0\nfor v in ventas:\ntotal += v\nprint(total)', 'ventas = [100, 200, 300]\ntotal = 0\nfor v in ventas:\n    total += v\nprint(total)', ['El cuerpo del for debe llevar sangría.', 'El print va fuera del bucle, sin sangría.']);
