  D('py-5', 'Este código da KeyError. Haz que imprima 0 cuando el producto no existe.', 'stock = {"mouse": 5}\nprint(stock["teclado"])', 'stock = {"mouse": 5}\nprint(stock.get("teclado", 0))', ['get permite un valor por defecto.']);
  P('py-6', 'def f(x, y=3):\n    return x * y\nprint(f(2) + f(2, 5))', 'f(2) usa y = 3 y da 6; f(2, 5) da 10. Suman 16.', 1);
  D('py-6', 'Debería imprimir 6.0 pero imprime None. Corrígelo.', 'def promedio(lista):\n    total = sum(lista) / len(lista)\nprint(promedio([4, 6, 8]))', 'def promedio(lista):\n    total = sum(lista) / len(lista)\n    return total\nprint(promedio([4, 6, 8]))', ['Una función sin return devuelve None.']);
