  D('py-7', 'Debería imprimir los precios caros de mayor a menor: [300, 120]. Corrígelo.', 'precios = [120, 45, 300]\ncaros = [p for p in precios if p > 100]\nprint(sorted(caros, reverse=False))', 'precios = [120, 45, 300]\ncaros = [p for p in precios if p > 100]\nprint(sorted(caros, reverse=True))', ['reverse=True ordena de mayor a menor.']);
  P('py-8', 'try:\n    r = 10 / 0\nexcept ZeroDivisionError:\n    r = -1\nfinally:\n    print("fin")\nprint(r)', 'La división falla, el except asigna -1 y finally se ejecuta siempre, con error o sin él.');
  D('py-8', 'Debería imprimir 5, inválido y 7, pero se detiene con un error. Corrígelo.', 'for t in ["5", "x", "7"]:\n    try:\n        print(int(t))\n    except TypeError:\n        print("inválido")', 'for t in ["5", "x", "7"]:\n    try:\n        print(int(t))\n    except ValueError:\n        print("inválido")', ['int("x") lanza un ValueError, no un TypeError.']);
  P('py-9', 'linea = "Mouse,3,250"\np, u, pr = linea.split(",")\nprint(int(u) * int(pr), p.upper())', 'split da tres textos; hay que convertir unidades y precio a número antes de multiplicar.', 1);
