  P('py-10', 'def leer(t):\n    return [int(x) for x in t.split(",") if x.strip()]\nprint(sum(leer("1, 2,,3")))', 'El campo vacío se descarta con if x.strip(); int acepta " 2" con espacio. 1 + 2 + 3 = 6.', 1);
  D('py-10', 'Debería imprimir 12 pero imprime 5. Corrígelo.', 'def total(filas):\n    s = 0\n    for f in filas:\n        s += f["monto"]\n        return s\nprint(total([{"monto": 5}, {"monto": 7}]))', 'def total(filas):\n    s = 0\n    for f in filas:\n        s += f["monto"]\n    return s\nprint(total([{"monto": 5}, {"monto": 7}]))', ['El return está dentro del bucle: sale en la primera vuelta.']);

  const PS = (id, code, explain) => add(id, { type: 'predict', level: 'Leer código', ask: 'rows', code, explain, prompt: 'Sin ejecutarla, ¿cuántas filas devuelve esta consulta? Usa la base de datos del curso.', hints: ['Piensa qué hace cada cláusula con las filas. Revisa la lección de la base si necesitas los conteos.'] });
