  add('sql-6', { level: 'Depurar', prompt: 'Debería listar los pedidos pendientes con el nombre de su cliente, pero los nombres no corresponden. Corrige la unión.', starter: "SELECT p.id, c.nombre FROM pedidos p JOIN clientes c ON c.id = p.id WHERE p.estado = 'Pendiente' ORDER BY p.id;", solution: "SELECT p.id, c.nombre FROM pedidos p JOIN clientes c ON c.id = p.cliente_id WHERE p.estado = 'Pendiente' ORDER BY p.id;", ordered: true, hints: ['La clave foránea del cliente en pedidos es cliente_id.'] });
  PS('sql-7', 'SELECT p.id FROM pedidos p JOIN detalle_pedidos d ON d.pedido_id = p.id WHERE p.id = 5;', 'El pedido 5 tiene cuatro líneas de detalle: el JOIN repite el pedido una vez por línea.');
  add('sql-7', { level: 'Depurar', prompt: 'Debería mostrar los 5 clientes con más pedidos, pero cuenta de más. Corrígela.', starter: 'SELECT c.nombre, COUNT(*) AS pedidos FROM pedidos p JOIN clientes c ON c.id = p.cliente_id JOIN detalle_pedidos d ON d.pedido_id = p.id GROUP BY c.id ORDER BY pedidos DESC, c.nombre LIMIT 5;', solution: 'SELECT c.nombre, COUNT(DISTINCT p.id) AS pedidos FROM pedidos p JOIN clientes c ON c.id = p.cliente_id JOIN detalle_pedidos d ON d.pedido_id = p.id GROUP BY c.id ORDER BY pedidos DESC, c.nombre LIMIT 5;', ordered: true, hints: ['Después del JOIN con el detalle, COUNT(*) cuenta líneas.'] });
  PS('sql-8', 'SELECT nombre FROM productos WHERE precio > (SELECT MAX(precio) FROM productos);', 'Ningún precio es mayor que el máximo: cero filas.');
  add('sql-8', { level: 'Depurar', prompt: 'Debería listar los empleados que no son jefe de nadie, en orden alfabético, pero no devuelve nada. Corrígela.', starter: 'SELECT nombre FROM empleados WHERE id NOT IN (SELECT jefe_id FROM empleados) ORDER BY nombre;', solution: 'SELECT nombre FROM empleados WHERE id NOT IN (SELECT jefe_id FROM empleados WHERE jefe_id IS NOT NULL) ORDER BY nombre;', ordered: true, hints: ['La subconsulta incluye un NULL (la directora no tiene jefe).', 'NOT IN con un NULL en la lista no devuelve filas.'] });
  PS('sql-9', "SELECT CASE WHEN precio >= 1000 THEN 'Alto' ELSE 'Bajo' END AS g, COUNT(*) FROM productos GROUP BY g;", 'CASE crea dos grupos posibles: Alto y Bajo.');
  add('sql-9', { level: 'Depurar', prompt: 'Debería clasificar Premium (3000 o más), Medio (800 o más) y Económico, pero ningún producto sale Premium. Corrígela.', starter: "SELECT nombre, CASE WHEN precio >= 800 THEN 'Medio' WHEN precio >= 3000 THEN 'Premium' ELSE 'Económico' END AS gama FROM productos ORDER BY nombre;", solution: "SELECT nombre, CASE WHEN precio >= 3000 THEN 'Premium' WHEN precio >= 800 THEN 'Medio' ELSE 'Económico' END AS gama FROM productos ORDER BY nombre;", ordered: true, hints: ['CASE se queda con el primer WHEN verdadero.'] });
